 import path from 'node:path';
 import fs from 'node:fs';
 import { pathToFileURL } from 'node:url';

 export async function resolve(specifier, context, defaultResolve) {
   if (specifier === 'next/server') {
     return defaultResolve('next/server.js', context);
   }
   if (specifier.startsWith('@/')) {
     const rawPath = path.resolve(process.cwd(), specifier.slice(2));
     let targetPath = rawPath;
     if (fs.existsSync(rawPath + '.ts')) {
       targetPath = rawPath + '.ts';
     } else if (fs.existsSync(path.join(rawPath, 'index.ts'))) {
       targetPath = path.join(rawPath, 'index.ts');
     }
     return {
       url: pathToFileURL(targetPath).href,
       shortCircuit: true,
     };
   }
   return defaultResolve(specifier, context);
 }

